	@Test
	void evalComplexConstructor() {
		// SBCL parity (.todo/751): a rational zero imaginary part demotes to the
		// real, a float zero stays complex (the int zero coerced to 0.0), mixed
		// rational/float coerces the rational side to float.
		assertThat(eval("(complex 1 2)")).isEqualTo(LispComplex.valueOf(new LispInteger(1), new LispInteger(2)));
		assertThat(eval("(complex 1 0)")).isEqualTo(new LispInteger(1));
		assertThat(eval("(complex 1)")).isEqualTo(new LispInteger(1));
		assertThat(eval("(complex 1/2 0)")).isEqualTo(new LispRatio(BigInteger.ONE, BigInteger.TWO));
		assertThat(eval("(complex 2.0 0)").print()).isEqualTo("#C(2.0 0.0)");
		assertThat(eval("(complex 1 0.0)").print()).isEqualTo("#C(1.0 0.0)");
		assertThat(eval("(complex 1 2.0)").print()).isEqualTo("#C(1.0 2.0)");
		assertThat(eval("(complex 0 1)")).isEqualTo(LispComplex.valueOf(new LispInteger(0), new LispInteger(1)));
	}

	@Test
	void evalComplexConstructorRejectsNonRealParts() {
		// Parts must be real: a nested complex (or any non-real) signals a
		// catchable type-error, like SBCL.
		assertThatThrownBy(() -> eval("(complex #c(1 2) 3)")).isInstanceOf(LispEvalException.class);
		assertThatThrownBy(() -> eval("(complex 1 \"a\")")).isInstanceOf(LispEvalException.class);
		assertThat(evalMulti("""
				(handler-case (complex #c(1 2) 3) (type-error (e) :caught))
				""")).isEqualTo(new LispSymbol(":CAUGHT"));
	}

	@Test
	void evalSharpCReader() {
		assertThat(eval("#C(1 2)")).isEqualTo(LispComplex.valueOf(new LispInteger(1), new LispInteger(2)));
		assertThat(eval("#c(1 2)")).isEqualTo(LispComplex.valueOf(new LispInteger(1), new LispInteger(2)));
		assertThat(eval("#C(1/2 1/3)").print()).isEqualTo("#C(1/2 1/3)");
		assertThat(eval("#C(1 0)").print()).isEqualTo("1");
		assertThat(eval("'#C(1 2)").print()).isEqualTo("#C(1 2)");
		assertThatThrownBy(() -> LispReader.readFromString("#C(1)")).isInstanceOf(LispReadException.class);
		assertThatThrownBy(() -> LispReader.readFromString("#C(1 2 3)")).isInstanceOf(LispReadException.class);
		assertThatThrownBy(() -> LispReader.readFromString("#C(#C(1 2) 3)")).isInstanceOf(LispReadException.class);
		assertThatThrownBy(() -> LispReader.readFromString("#C(a b)")).isInstanceOf(LispReadException.class);
	}

	@Test
	void evalComplexArithmeticStaysExact() {
		// Exact rationals stay exact (SBCL parity).
		assertThat(eval("(+ #c(1 1/2) #c(1 1/3))").print()).isEqualTo("#C(2 5/6)");
		assertThat(eval("(- #c(1 2) #c(3 4))").print()).isEqualTo("#C(-2 -2)");
		assertThat(eval("(- #c(1 2))").print()).isEqualTo("#C(-1 -2)");
		assertThat(eval("(* #c(1 2) 2)").print()).isEqualTo("#C(2 4)");
		assertThat(eval("(/ #c(1 2) 2)").print()).isEqualTo("#C(1/2 1)");
		assertThat(eval("(/ #c(1 2))").print()).isEqualTo("#C(1/5 -2/5)");
		assertThat(eval("(+ #c(1 2) #c(3 4) 1)").print()).isEqualTo("#C(5 6)");
		assertThat(eval("(1+ #c(1 2))").print()).isEqualTo("#C(2 2)");
		assertThat(eval("(1- #c(1 2))").print()).isEqualTo("#C(0 2)");
		assertThat(eval("(- #c(0 1) #c(0 1))")).isEqualTo(new LispInteger(0));
	}

	@Test
	void evalComplexArithmeticContagion() {
		// A float anywhere coerces the whole computation to float (SBCL parity).
		assertThat(eval("(+ #c(1 2) 1.5)").print()).isEqualTo("#C(2.5 2.0)");
		assertThat(eval("(* #c(1 2) 2.0)").print()).isEqualTo("#C(2.0 4.0)");
		assertThat(eval("(- 1 #c(1 2))").print()).isEqualTo("#C(0 -2)");
	}

	@Test
	void evalComplexFloatDivisionIsSmithsForm() {
		// Float complex division folds on the LARGER divisor part (Smith's form, what
		// SBCL 2.2.9 computes) instead of dividing by c^2+d^2. A REAL divisor makes the
		// fold's r zero, so each part costs ONE rounding: this quotient is SBCL's
		// #C(3.0 4.532360141827194), where the denominator form answered
		// 2.9999999999999996 for the real part.
		assertThat(eval("(/ #c(2.0794415416798357d0 3.141592653589793d0) 0.6931471805599453d0)").print())
			.isEqualTo("#C(3.0 4.532360141827194)");
		assertThat(realPartOf("(/ #c(1d0 2d0) 3d0)")).isEqualTo(1.0 / 3.0);
		assertThat(imagPartOf("(/ #c(1d0 2d0) 3d0)")).isEqualTo(2.0 / 3.0);
		// Nothing intermediate leaves the operands' own range: c^2+d^2 overflows above
		// |c| ~ 1.3e154 and flushes to zero below ~1.5e-162, and both of these answered
		// #C(NaN NaN) through it.
		assertThat(eval("(/ #c(1d200 1d200) #c(1d200 1d200))").print()).isEqualTo("#C(1.0 0.0)");
		assertThat(eval("(/ #c(1d-200 1d-200) #c(1d-200 1d-200))").print()).isEqualTo("#C(1.0 0.0)");
		assertThat(realPartOf("(/ #c(1d0 2d0) #c(1d300 1d300))")).isEqualTo(3.0 / (2.0 * 1e300));
		assertThat(imagPartOf("(/ #c(1d0 2d0) #c(1d300 1d300))")).isEqualTo(1.0 / (2.0 * 1e300));
		// Both arms of the fold, and the values every form already agreed on.
		assertThat(eval("(/ #c(1d0 2d0) #c(3d0 4d0))").print()).isEqualTo("#C(0.44 0.08)");
		assertThat(eval("(/ #c(1d0 2d0) #c(4d0 3d0))").print()).isEqualTo("#C(0.4 0.2)");
		assertThat(eval("(/ #c(1d0 2d0) #c(0d0 1d0))").print()).isEqualTo("#C(2.0 -1.0)");
		assertThat(eval("(/ 3d0 #c(1d0 2d0))").print()).isEqualTo("#C(0.6 -1.2)");
		// A zero FLOAT divisor keeps the NaN the denominator form answered (r is 0/0):
		// SBCL signals DIVISION-BY-ZERO there because its FPU traps, this runtime does
		// not trap, and a part-wise infinity would claim an answer where there is none.
		assertThat(realPartOf("(/ #c(1d0 2d0) 0d0)")).isNaN();
		assertThat(imagPartOf("(/ #c(1d0 2d0) 0d0)")).isNaN();
		assertThat(realPartOf("(/ #c(1d0 2d0) #c(0d0 0d0))")).isNaN();
		// The EXACT arm is untouched, division by an exact zero included.
		assertThat(eval("(/ #c(1 2) #c(3 4))").print()).isEqualTo("#C(11/25 2/25)");
		assertThatThrownBy(() -> eval("(/ #c(1 2) 0)")).hasMessageContaining("Division by zero");
	}

	@Test
	void evalComplexAbs() {
		// abs answers a real (a float even for exact parts, like SBCL).
		assertThat(eval("(abs #c(3 4))")).isEqualTo(new LispDouble(5.0));
		assertThat(eval("(abs #c(3 4))").print()).isEqualTo("5.0");
		assertThat(eval("(abs 5)")).isEqualTo(new LispInteger(5));
	}

	@Test
	void evalComplexSqrt() {
		// A negative real roots into the complex plane (SBCL parity); a
		// non-negative real still answers a double.
		assertThat(eval("(sqrt -1)").print()).isEqualTo("#C(0.0 1.0)");
		assertThat(eval("(sqrt -4)").print()).isEqualTo("#C(0.0 2.0)");
		assertThat(eval("(sqrt #c(3 4))").print()).isEqualTo("#C(2.0 1.0)");
		assertThat(eval("(sqrt 4)")).isEqualTo(new LispDouble(2.0));
	}

	@Test
	void evalComplexEquality() {
		assertThat(eval("(= #c(1 2) #c(1 2))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(= 2.0 #c(2.0 0.0))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(= #c(1 2) 1)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(= #c(1 2) #c(1 3))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(eql 1 #c(1 0))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(eql 2.0 #c(2.0 0))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(eql #c(1 2) #c(1 2))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(equal #c(1 2) #c(1 2))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(/= #c(1 2) #c(1 3))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(/= #c(1 2) #c(1 2))")).isSameAs(LispNil.INSTANCE);
	}

	@Test
	void evalComplexPredicates() {
		assertThat(eval("(complexp #c(1 2))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(complexp 1)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(numberp #c(1 2))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(numberp 1)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(realp #c(1 2))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(realp 1)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(realp 1.5)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(realp 1/2)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(realp nil)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(integerp #c(1 2))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(floatp #c(1.0 2.0))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(rationalp #c(1 2))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(zerop #c(0 0))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(zerop #c(0.0 0.0))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(zerop #c(1 2))")).isSameAs(LispNil.INSTANCE);
	}

	@Test
	void aConditionCarryingRenderedTextReportsItOnce() {
		// A signal's message and a built-in failure's text are already rendered; the
		// condition stores each as the control that renders it verbatim, so a ~ in the
		// text is never a directive of the report. The compile-path twins are
		// JvmLispCompilerTest / WasmLispCompilerIntegrationTest
		// #aConditionCarryingRenderedTextReportsItOnce, the four-backend pin ci-spec's
		// condition-report-prints-rendered-text-once.
		assertThat(evalMulti("""
				(defun te (thunk) (handler-case (funcall thunk) (type-error (e) (princ-to-string e))))
				(list (handler-case (error "a~~b") (error (e) (princ-to-string e)))
				      (handler-case (car "~a") (error (e) (princ-to-string e)))
				      (te (lambda () (+ 1 "~a")))
				      (handler-case (error "a~~b") (error (e) (simple-condition-format-control e)))
				      (handler-case (error "~a" "~/x/ 100~%") (error (e) (princ-to-string e)))
				      (handler-case (signal "s~~t") (condition (e) (princ-to-string e)))
				      (handler-case (error (make-condition 'simple-error :format-control "u~~v"))
				        (error (e) (princ-to-string e))))
				""").print()).isEqualTo("(\"a~b\" \"CAR: The value \\\"~a\\\" is not of type LIST\""
				+ " \"+: The value \\\"~a\\\" is not of type NUMBER\" \"a~~b\" \"~/x/ 100~%\" \"s~t\" \"u~v\")");
	}

	@Test
	void evalComplexOrderingSignalsCatchableTypeErrors() {
		// Ordering (and min/max, plusp/minusp) over a complex signals a catchable
		// type-error (SBCL parity).
		assertThat(evalMulti("""
				(defun te-print (thunk)
				  (handler-case (funcall thunk) (type-error (e) (princ-to-string e))))
				(list (te-print (lambda () (minusp #c(1 2))))
				      (te-print (lambda () (plusp #c(1 2))))
				      (te-print (lambda () (< #c(1 2) #c(3 4))))
				      (te-print (lambda () (> #c(1 2) 1)))
				      (te-print (lambda () (min #c(1 2) 3)))
				      (te-print (lambda () (max 3 #c(1 2)))))
				""").print()).isEqualTo("(\"<: The value #C(1 2) is not of type REAL\""
				+ " \">: The value #C(1 2) is not of type REAL\"" + " \"<: The value #C(1 2) is not of type REAL\""
				+ " \">: The value #C(1 2) is not of type REAL\"" + " \"MIN: The value #C(1 2) is not of type REAL\""
				+ " \"MAX: The value #C(1 2) is not of type REAL\")");
	}

	@Test
	void evalComplexAccessors() {
		assertThat(eval("(conjugate #c(1 2))").print()).isEqualTo("#C(1 -2)");
		assertThat(eval("(conjugate 5)")).isEqualTo(new LispInteger(5));
		assertThat(eval("(realpart #c(1 2))")).isEqualTo(new LispInteger(1));
		assertThat(eval("(realpart 5)")).isEqualTo(new LispInteger(5));
		assertThat(eval("(realpart #c(1.0 2))")).isEqualTo(new LispDouble(1.0));
		assertThat(eval("(imagpart #c(1 2))")).isEqualTo(new LispInteger(2));
		assertThat(eval("(imagpart 5)")).isEqualTo(new LispInteger(0));
		assertThat(eval("(imagpart 5.5)")).isEqualTo(new LispDouble(0.0));
		assertThat(eval("(phase #c(1 1))")).isEqualTo(new LispDouble(Math.PI / 4));
		assertThat(eval("(phase 5)")).isEqualTo(new LispDouble(0.0));
		assertThat(eval("(phase -5)")).isEqualTo(new LispDouble(Math.PI));
		assertThatThrownBy(() -> eval("(realpart nil)")).isInstanceOf(LispEvalException.class);
	}

	@Test
	void evalImagpartSignedZero() {
		// CLHS: (imagpart x) of a real IS (* 0 x) -- the sign of zero survives,
		// like SBCL. eql itself is untouched (bit semantics, .kb/linalg-simd.md).
		assertThat(Double.doubleToRawLongBits(((LispDouble) eval("(imagpart -1.0)")).value()))
			.isEqualTo(Double.doubleToRawLongBits(-0.0));
		assertThat(Double.doubleToRawLongBits(((LispDouble) eval("(imagpart 1.0)")).value()))
			.isEqualTo(Double.doubleToRawLongBits(0.0));
		assertThat(eval("(eql (* 0 -1.0) (imagpart -1.0))")).isEqualTo(LispTrue.INSTANCE);
		assertThat(eval("(eql (* 0 1.0) (imagpart 1.0))")).isEqualTo(LispTrue.INSTANCE);
		assertThat(eval("(imagpart -2)")).isEqualTo(new LispInteger(0));
		assertThat(eval("(imagpart #c(1 2))")).isEqualTo(new LispInteger(2));
	}

	@Test
	void evalComplexExptExpLogTrig() {
		// An integer exponent over complex parts stays exact (SBCL parity).
		assertThat(eval("(expt #c(1 1) 2)").print()).isEqualTo("#C(0 2)");
		assertThat(eval("(expt #c(1 1) -1)").print()).isEqualTo("#C(1/2 -1/2)");
		assertThat(eval("(expt #c(0 1) 2)")).isEqualTo(new LispInteger(-1));
		assertThat(eval("(exp #c(0 1))").print()).isEqualTo("#C(0.5403023058681398 0.8414709848078965)");
		// log's real part is StrictMath.log(StrictMath.hypot(1, 1)): 1 ulp above the
		// infinitely precise ln(sqrt(2)) -- the same call every backend makes, so
		// all four pin this spelling.
		assertThat(eval("(log #c(1 1))").print()).isEqualTo("#C(0.3465735902799727 0.7853981633974483)");
		assertThat(eval("(sin #c(1 1))").print()).isEqualTo("#C(1.2984575814159773 0.6349639147847361)");
		assertThat(eval("(exp 1)")).isEqualTo(new LispDouble(StrictMath.exp(1)));
		assertThat(eval("(expt 2 3)")).isEqualTo(new LispInteger(8));
	}

	@Test
	void evalComplexAsinAcosOnTheBranchCut() {
		// asin and acos cut the real axis outside [-1, 1], and CLHS fixes which side
		// the value ON the cut is continuous with by the sign of the REAL part:
		// quadrant IV above +1, quadrant II below -1. The sign of an imaginary ZERO
		// does NOT move it (SBCL parity, `.kb/jvm-complex.md`) -- unlike sqrt and log,
		// where it does -- so both zero signs are pinned here and the contract cannot
		// drift back. The real parts are atan2's exact on-axis answers; the imaginary
		// magnitudes are asinh of the sqrt product, whose last ulp is the PLATFORM's
		// Math.log, so they spell the call the code makes.
		String asinAboveOne = "#C(1.5707963267948966 " + -StrictMath.log(3.7320508075688767) + ")";
		assertThat(eval("(asin #c(2d0 0d0))").print()).isEqualTo(asinAboveOne);
		assertThat(eval("(asin #c(2d0 -0d0))").print()).isEqualTo(asinAboveOne);
		String asinBelowMinusOne = "#C(-1.5707963267948966 " + StrictMath.log(7.872983346207417) + ")";
		assertThat(eval("(asin #c(-4d0 0d0))").print()).isEqualTo(asinBelowMinusOne);
		assertThat(eval("(asin #c(-4d0 -0d0))").print()).isEqualTo(asinBelowMinusOne);
		String acosAboveOne = "#C(0.0 " + StrictMath.log(3.7320508075688767) + ")";
		assertThat(eval("(acos #c(2d0 0d0))").print()).isEqualTo(acosAboveOne);
		assertThat(eval("(acos #c(2d0 -0d0))").print()).isEqualTo(acosAboveOne);
		String acosBelowMinusOne = "#C(3.141592653589793 " + -StrictMath.log(7.872983346207417) + ")";
		assertThat(eval("(acos #c(-4d0 0d0))").print()).isEqualTo(acosBelowMinusOne);
		assertThat(eval("(acos #c(-4d0 -0d0))").print()).isEqualTo(acosBelowMinusOne);
		// Off the cut nothing is ambiguous: the limit from the quadrant the cut is
		// continuous with carries the SAME imaginary part as the value on it, and the
		// limit from the other side carries its negation.
		assertThat(eval("(asin (complex 2d0 -1d-10))").print())
			.isEqualTo("#C(1.5707963267371616 " + -StrictMath.log(3.7320508075688767) + ")");
		assertThat(eval("(asin (complex 2d0 1d-10))").print())
			.isEqualTo("#C(1.5707963267371616 " + StrictMath.log(3.7320508075688767) + ")");
		assertThat(eval("(asin (complex -4d0 1d-10))").print())
			.isEqualTo("#C(-1.5707963267690768 " + StrictMath.log(7.872983346207417) + ")");
		assertThat(eval("(asin (complex -4d0 -1d-10))").print())
			.isEqualTo("#C(-1.5707963267690768 " + -StrictMath.log(7.872983346207417) + ")");
	}

	@Test
	void evalComplexAsinAcosOfARealArgumentAnswerAnExactZero() {
		// A complex argument on the real axis inside [-1, 1] answers an EXACTLY real
		// value: the imaginary part is a difference of zeros fed to asinh, which
		// answers +0.0 for it. (The -i*log(i*z + sqrt(1 - z^2)) form this replaced
		// leaked 2^-53 out of the logarithm instead.)
		assertThat(eval("(asin (complex -0.5d0 0d0))").print()).isEqualTo("#C(-0.5235987755982989 0.0)");
		assertThat(eval("(asin (complex 0.5d0 0d0))").print()).isEqualTo("#C(0.5235987755982989 0.0)");
		assertThat(eval("(asin (complex 0d0 0d0))").print()).isEqualTo("#C(0.0 0.0)");
		assertThat(eval("(asin (complex 1d0 0d0))").print()).isEqualTo("#C(1.5707963267948966 0.0)");
		assertThat(eval("(asin (complex -1d0 0d0))").print()).isEqualTo("#C(-1.5707963267948966 0.0)");
		assertThat(eval("(acos (complex -0.5d0 0d0))").print()).isEqualTo("#C(2.0943951023931953 0.0)");
		assertThat(eval("(acos (complex 0.5d0 0d0))").print()).isEqualTo("#C(1.0471975511965979 0.0)");
		assertThat(eval("(acos (complex 0d0 0d0))").print()).isEqualTo("#C(1.5707963267948966 0.0)");
		assertThat(eval("(acos (complex 1d0 0d0))").print()).isEqualTo("#C(0.0 0.0)");
		assertThat(eval("(acos (complex -1d0 0d0))").print()).isEqualTo("#C(3.141592653589793 0.0)");
		// asin(z) = -i*asinh(i*z) and acos(z) = -i*acosh(z) hold to the BIT against the
		// inverse hyperbolics pinned above, which the old formula missed by 2 ulp.
		assertThat(eval("(asin #c(0d0 1d0))").print()).isEqualTo("#C(0.0 0.881373587019543)");
		assertThat(eval("(asin #c(1d0 1d0))").print())
			.isEqualTo("#C(0.6662394324925153 " + StrictMath.log(2.890053638263964) + ")");
		assertThat(eval("(acos #c(0d0 1d0))").print()).isEqualTo("#C(1.5707963267948966 -0.881373587019543)");
		assertThat(eval("(acos #c(1d0 1d0))").print())
			.isEqualTo("#C(0.9045568943023813 " + -StrictMath.log(2.890053638263964) + ")");
	}

	@Test
	void evalComplexAsinAcosRoundTrip() {
		// sin(asin z) and cos(acos z) return z, on the cut as well as off it. Which
		// ulp they land on follows the platform's Math.log through the asinh, so the
		// accuracy is the pin and the digits are not.
		for (String z : List.of("#c(0d0 1d0)", "#c(1d0 1d0)", "#c(2d0 0d0)", "#c(-4d0 0d0)")) {
			double re = ((LispDouble) eval("(realpart " + z + ")")).value();
			double im = ((LispDouble) eval("(imagpart " + z + ")")).value();
			assertThat(((LispDouble) eval("(realpart (sin (asin " + z + ")))")).value()).isCloseTo(re,
					within(4 * Math.ulp(Math.max(Math.abs(re), 1.0))));
			assertThat(((LispDouble) eval("(imagpart (sin (asin " + z + ")))")).value()).isCloseTo(im,
					within(4 * Math.ulp(Math.max(Math.abs(im), 1.0))));
			assertThat(((LispDouble) eval("(realpart (cos (acos " + z + ")))")).value()).isCloseTo(re,
					within(4 * Math.ulp(Math.max(Math.abs(re), 1.0))));
			assertThat(((LispDouble) eval("(imagpart (cos (acos " + z + ")))")).value()).isCloseTo(im,
					within(4 * Math.ulp(Math.max(Math.abs(im), 1.0))));
		}
	}

	@Test
	void evalComplexTanTanhAreQuotientsOnEveryAxis() {
		// The reference half of
		// JvmLispCompilerTest#compileAndRunComplexUnaryMathMirrorsTheInterpreterArmForArm:
		// that differential can only see a DISAGREEMENT, so the value it agrees on is
		// anchored here against the real functions. Each axis of complex tan/tanh is the
		// real function of one family, and the JVM's slot reuse (.todo/765) broke exactly
		// this: losing the denominator left the numerator, so tan of a real was sin of
		// it. The digits are the platform's Math, so closeness is the pin.
		assertThat(((LispDouble) eval("(realpart (tan #c(1d0 0d0)))")).value()).isCloseTo(StrictMath.tan(1.0),
				within(4 * Math.ulp(StrictMath.tan(1.0))));
		assertThat(((LispDouble) eval("(imagpart (tan #c(0d0 1d0)))")).value()).isCloseTo(StrictMath.tanh(1.0),
				within(4 * Math.ulp(1.0)));
		assertThat(((LispDouble) eval("(realpart (tanh #c(1d0 0d0)))")).value()).isCloseTo(StrictMath.tanh(1.0),
				within(4 * Math.ulp(1.0)));
		assertThat(((LispDouble) eval("(imagpart (tanh #c(0d0 1d0)))")).value()).isCloseTo(StrictMath.tan(1.0),
				within(4 * Math.ulp(StrictMath.tan(1.0))));
		// Off the axes both are still the quotient of their own sine by their own cosine.
		assertThat(((LispDouble) eval("(abs (- (tan #c(1d0 1d0)) (/ (sin #c(1d0 1d0)) (cos #c(1d0 1d0)))))")).value())
			.isCloseTo(0.0, within(1e-15));
		assertThat(
				((LispDouble) eval("(abs (- (tanh #c(1d0 1d0)) (/ (sinh #c(1d0 1d0)) (cosh #c(1d0 1d0)))))")).value())
			.isCloseTo(0.0, within(1e-15));
	}

	@Test
	void evalComplexFirstClass() {
		assertThat(eval("(funcall #'complex 1 2)").print()).isEqualTo("#C(1 2)");
		assertThat(eval("(funcall #'conjugate #c(1 2))").print()).isEqualTo("#C(1 -2)");
		assertThat(eval("(mapcar #'complexp (list #c(1 2) 1))").print()).isEqualTo("(T NIL)");
	}

	@Test
	void evalComplexTypep() {
		// SBCL parity (.todo/754): a complex is of type complex (and of type
		// number) but not of type real; a real is not of type complex.
		assertThat(eval("(typep #c(1 2) 'complex)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep #c(1 2) 'real)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(typep #c(1 2) 'number)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep 5 'complex)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(typep 5 'real)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep 5 'number)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep #c(1 2) '(complex integer))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep #c(1.0 2.0) '(complex integer))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(typep #c(1.0 2.0) '(complex single-float))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep #c(1 2) '(complex *))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep 5 '(complex *))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(typep #c(1 2) '(complex rational))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(typep #c(1 2) 'complex)")).isSameAs(LispTrue.INSTANCE);
		// typecase/etypecase/check-type ride the same specifier mapping.
		assertThat(eval("(typecase #c(1 2) (real :real) (complex :complex))")).isEqualTo(new LispSymbol(":COMPLEX"));
		assertThat(eval("(typecase 5 (complex :complex) (real :real))")).isEqualTo(new LispSymbol(":REAL"));
		assertThat(evalMulti("""
				(check-type #c(1 2) complex)
				:checked
				""")).isEqualTo(new LispSymbol(":CHECKED"));
		assertThatThrownBy(() -> eval("(check-type 5 complex)")).isInstanceOf(LispEvalException.class);
	}

	@Test
	void evalComplexTypeOfAndSubtypep() {
		// type-of answers the atomic COMPLEX (the numeric convention here is atomic,
		// unlike SBCL's bounded (COMPLEX (INTEGER ...))); the round trip holds.
		assertThat(eval("(type-of #c(1 2))")).isEqualTo(new LispSymbol("COMPLEX"));
		assertThat(eval("(typep #c(1 2) (type-of #c(1 2)))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(subtypep 'complex 'number)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(subtypep 'real 'number)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(subtypep 'complex 'real)")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(subtypep '(complex integer) 'complex)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(subtypep '(complex integer) '(complex rational))")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(subtypep 'complex '(complex integer))")).isSameAs(LispNil.INSTANCE);
		assertThat(eval("(subtypep '(complex integer) 'number)")).isSameAs(LispTrue.INSTANCE);
		assertThat(eval("(class-of #c(1 2))")).isEqualTo(eval("(find-class 'complex)"));
	}

	@Test
	void evalSubtypepOverCircularDeftypes() {
		// postmodern's s-sql declares (deftype tsvector () 'tsvector); a circular name
		// is an unknown type, not an endless expansion.
		String defs = """
				(deftype sc-self () 'sc-self)
				(deftype sc-ping () '(or sc-pong integer))
				(deftype sc-pong () '(or sc-ping string))
				""";
		assertThat(evalMulti(defs + "(subtypep 'fixnum 'sc-self)")).isSameAs(LispNil.INSTANCE);
		assertThat(evalMulti(defs + "(subtypep 'sc-self 'integer)")).isSameAs(LispNil.INSTANCE);
		assertThat(evalMulti(defs + "(subtypep 'sc-self 'sc-self)")).isSameAs(LispTrue.INSTANCE);
		assertThat(evalMulti(defs + "(subtypep 'fixnum 'sc-ping)")).isSameAs(LispTrue.INSTANCE);
		assertThat(evalMulti(defs + "(subtypep 'character 'sc-ping)")).isSameAs(LispNil.INSTANCE);
	}

	@Test
	void evalUpgradedComplexPartType() {
		// SBCL parity (.todo/754, host 2.2.9): a real-subtype name answers itself, a
		// compound real specifier answers its head's name, anything else signals.
		assertThat(eval("(upgraded-complex-part-type 'integer)")).isEqualTo(new LispSymbol("INTEGER"));
		assertThat(eval("(upgraded-complex-part-type 'single-float)")).isEqualTo(new LispSymbol("SINGLE-FLOAT"));
		assertThat(eval("(upgraded-complex-part-type 'float)")).isEqualTo(new LispSymbol("FLOAT"));
		assertThat(eval("(upgraded-complex-part-type 'real)")).isEqualTo(new LispSymbol("REAL"));
		assertThat(eval("(upgraded-complex-part-type 'ratio)")).isEqualTo(new LispSymbol("RATIO"));
		assertThat(eval("(upgraded-complex-part-type '(integer 0 10))")).isEqualTo(new LispSymbol("INTEGER"));
		assertThat(eval("(funcall #'upgraded-complex-part-type 'integer)")).isEqualTo(new LispSymbol("INTEGER"));
		assertThatThrownBy(() -> eval("(upgraded-complex-part-type 'string)")).isInstanceOf(LispEvalException.class);
		assertThatThrownBy(() -> eval("(upgraded-complex-part-type 'complex)")).isInstanceOf(LispEvalException.class);
		assertThatThrownBy(() -> eval("(upgraded-complex-part-type 'number)")).isInstanceOf(LispEvalException.class);
		assertThat(evalMulti("""
				(handler-case (upgraded-complex-part-type 'string) (error (e) :caught))
				""")).isEqualTo(new LispSymbol(":CAUGHT"));
	}

	@Test
	void evalCoerceToComplex() {
		// SBCL parity (.todo/754): a real demotes when exact (5 stays 5), a float
		// stays complex, a complex answers itself, a part-typed target coerces both
		// parts first, and a real target answers a real as is.
		assertThat(eval("(coerce 5 'complex)")).isEqualTo(new LispInteger(5));
		assertThat(eval("(coerce 5.0 'complex)").print()).isEqualTo("#C(5.0 0.0)");
		assertThat(eval("(coerce 1/2 'complex)")).isEqualTo(new LispRatio(BigInteger.ONE, BigInteger.TWO));
		assertThat(eval("(coerce #c(1 2) 'complex)").print()).isEqualTo("#C(1 2)");
		assertThat(eval("(coerce 5 '(complex single-float))").print()).isEqualTo("#C(5.0 0.0)");
		assertThat(eval("(coerce #c(1 2) '(complex single-float))").print()).isEqualTo("#C(1.0 2.0)");
		assertThat(eval("(coerce #c(1.0 2.0) '(complex single-float))").print()).isEqualTo("#C(1.0 2.0)");
		assertThat(eval("(coerce 5 'real)")).isEqualTo(new LispInteger(5));
		assertThat(evalMulti("""
				(defun pick-complex-type () 'complex)
				(coerce 5.0 (pick-complex-type))
				""").print()).isEqualTo("#C(5.0 0.0)");
		assertThat(evalMulti("""
				(handler-case (coerce #c(1 2) 'real) (type-error (e) :caught))
				""")).isEqualTo(new LispSymbol(":CAUGHT"));
		assertThat(evalMulti("""
				(handler-case (coerce #c(1 2) 'single-float) (type-error (e) :caught))
				""")).isEqualTo(new LispSymbol(":CAUGHT"));
	}

	@Test
	void evalComplexSignum() {
		// SBCL parity (.todo/754): the unit vector z/|z| in floats; a zero answers
		// the canonicalization of its own parts (0 for exact, #C(0.0 0.0) for float).
		assertThat(eval("(signum #c(3 4))").print()).isEqualTo("#C(0.6 0.8)");
		assertThat(eval("(signum #c(0 0))")).isEqualTo(new LispInteger(0));
		assertThat(eval("(signum #c(0.0 0.0))").print()).isEqualTo("#C(0.0 0.0)");
		assertThat(eval("(signum #c(0 1))").print()).isEqualTo("#C(0.0 1.0)");
		assertThat(eval("(funcall #'signum #c(3 4))").print()).isEqualTo("#C(0.6 0.8)");
	}

	@Test
	void evalComplexRealOnlyOperationsSignalCatchableTypeErrors() {
		// Real-only by contract (.todo/754): isqrt, the floor family, mod/rem,
		// gcd/lcm, the bitwise operators, float and numerator/denominator signal a
		// catchable type-error over a complex (SBCL parity; the message prefix is
		// what the compiled backends mirror byte-identical).
		assertThat(evalMulti("""
				(defun te-print (thunk)
				  (handler-case (funcall thunk) (type-error (e) (princ-to-string e))))
				(list (te-print (lambda () (floor #c(1 2))))
				      (te-print (lambda () (truncate #c(1 2))))
				      (te-print (lambda () (ceiling #c(1 2))))
				      (te-print (lambda () (round #c(1 2))))
				      (te-print (lambda () (float #c(1 2))))
				      (te-print (lambda () (numerator #c(1 2))))
				      (te-print (lambda () (denominator #c(1 2)))))
				""").print()).isEqualTo("(\"FLOOR: The value #C(1 2) is not of type REAL\""
				+ " \"TRUNCATE: The value #C(1 2) is not of type REAL\""
				+ " \"CEILING: The value #C(1 2) is not of type REAL\""
				+ " \"ROUND: The value #C(1 2) is not of type REAL\""
				+ " \"FLOAT: The value #C(1 2) is not of type REAL\""
				+ " \"NUMERATOR: The value #C(1 2) is not of type RATIONAL\""
				+ " \"DENOMINATOR: The value #C(1 2) is not of type RATIONAL\")");
		assertThat(evalMulti("""
				(defun te-print (thunk)
				  (handler-case (funcall thunk) (type-error (e) (princ-to-string e))))
				(list (te-print (lambda () (isqrt #c(1 2))))
				      (te-print (lambda () (mod #c(1 2) 3)))
				      (te-print (lambda () (rem #c(1 2) 3)))
				      (te-print (lambda () (gcd #c(1 2) 3)))
				      (te-print (lambda () (lcm 4 #c(1 2))))
				      (te-print (lambda () (logand #c(1 2) 3)))
				      (te-print (lambda () (ash #c(1 2) 1))))
				""").print()).isEqualTo("(\"ISQRT: The value #C(1 2) is not of type INTEGER\""
				+ " \"MOD: The value #C(1 2) is not of type REAL\"" + " \"REM: The value #C(1 2) is not of type REAL\""
				+ " \"GCD: The value #C(1 2) is not of type INTEGER\""
				+ " \"LCM: The value #C(1 2) is not of type INTEGER\""
				+ " \"LOGAND: The value #C(1 2) is not of type INTEGER\""
				+ " \"ASH: The value #C(1 2) is not of type INTEGER\")");
	}

