	@Test
	void readWriteSequenceRoundTrip(@TempDir Path tempDir) {
		String file = tempDir.resolve("seq.dat").toString().replace("\\", "\\\\");
		LispVal result = evalMulti("""
				(setq buf (make-array 4))
				(setf (aref buf 0) 65)
				(setf (aref buf 1) 0)
				(setf (aref buf 2) 10)
				(setf (aref buf 3) 34)
				(with-open-file (out "%s" :direction :output :element-type '(unsigned-byte 8))
				  (write-sequence buf out))
				(setq buf2 (make-array 4 :initial-element nil))
				(with-open-file (in "%s" :element-type '(unsigned-byte 8))
				  (list (read-sequence buf2 in) (aref buf2 0) (aref buf2 1) (aref buf2 2) (aref buf2 3)))
				""".formatted(file, file));
		assertThat(result.print()).isEqualTo("(4 65 0 10 34)");
	}

	// A #bf16 array moves as its STORED PATTERNS -- two little-endian bytes an element,
	// which is what a BF16 safetensors or GGUF tensor holds -- so such a file loads with
	// no conversion and writing it back reproduces the bytes. The value is chosen so a
	// byte-swap could not pass unnoticed: bf16 0x3F80 is exactly 1.0, and the swapped
	// 0x803F is a tiny negative denormal (.kb/bfloat16.md, .todo/487 step 3).
	@Test
	void readWriteSequenceMovesABfloat16ArrayAsItsStoredPatterns(@TempDir Path tempDir) {
		String file = tempDir.resolve("bf16.dat").toString().replace("\\", "\\\\");
		LispVal result = evalMulti("""
				(defvar *src* (make-array 3 :element-type 'bfloat16))
				(setf (aref *src* 0) 1.0)
				(setf (aref *src* 1) -2.0)
				(setf (aref *src* 2) 0.5)
				(with-open-file (out "%s" :direction :output :element-type '(unsigned-byte 8)
				                 :if-exists :supersede)
				  (write-sequence *src* out))
				;; The bytes on the wire, read back as raw 16-bit words: the stored
				;; patterns themselves, little-endian.
				(defvar *bits* (make-array 3 :element-type '(unsigned-byte 16)))
				(with-open-file (in "%s" :element-type '(unsigned-byte 8))
				  (read-sequence *bits* in))
				(defvar *back* (make-array 3 :element-type 'bfloat16))
				(with-open-file (in "%s" :element-type '(unsigned-byte 8))
				  (list (read-sequence *back* in) (aref *bits* 0) (aref *back* 0) (aref *back* 1)
				        (aref *back* 2)))
				""".formatted(file, file, file));
		assertThat(result.print()).as("bf16 1.0 is 0x3F80 = 16256; a byte swap would read 0x803F = 32831")
			.isEqualTo("(3 16256 1.0 -2.0 0.5)");
	}

	@Test
	void readWriteSequencePackedBuffersMoveRawLittleEndianElements(@TempDir Path tempDir) {
		// A packed buffer -- a packed float array of any rank, a packed
		// (unsigned-byte 8|16|32) vector -- moves as raw little-endian elements in
		// one bulk transfer; a general vector still receives one byte per element
		// (.kb/binary-sequence-io.md).
		String file = tempDir.resolve("pk.dat").toString().replace("\\", "\\\\");
		java.io.ByteArrayOutputStream captured = new java.io.ByteArrayOutputStream();
		LispEvaluator evaluator = new LispEvaluator(new PrintStream(captured, true, StandardCharsets.UTF_8));
		for (LispVal expr : LispReader.readAllFromString(
				"""
						(with-open-file (out "%s" :direction :output :element-type '(unsigned-byte 8))
						  (write-sequence #f(1.5 -2.25 3.0e10) out)
						  (write-sequence #d((0.5 -0.0) (0.1 42.0)) out)
						  (write-sequence (make-array 3 :element-type '(unsigned-byte 16) :initial-contents '(1 65535 258)) out)
						  (write-sequence (make-array 2 :element-type '(unsigned-byte 32) :initial-contents '(65536 4294967295)) out))
						(with-open-file (in "%s" :element-type '(unsigned-byte 8))
						  (let ((f (make-array 3 :element-type 'single-float :initial-element 0.0))
						        (d (make-array '(2 2) :element-type 'double-float :initial-element 0.0))
						        (u16 (make-array 3 :element-type '(unsigned-byte 16)))
						        (u32 (make-array 2 :element-type '(unsigned-byte 32))))
						    (print (list (read-sequence f in) (read-sequence d in) (read-sequence u16 in) (read-sequence u32 in)))
						    (print f) (print d) (print u16) (print u32)))
						(with-open-file (in "%s" :element-type '(unsigned-byte 8))
						  (let ((b (make-array 4 :element-type '(unsigned-byte 8))))
						    (read-sequence b in)
						    (print b)))
						(with-open-file (in "%s" :element-type '(unsigned-byte 8))
						  (let ((f (make-array 6 :element-type 'single-float :initial-element 9.0)))
						    (print (read-sequence f in :start 1 :end 3))
						    (print f)))
						(with-open-file (in "%s" :element-type '(unsigned-byte 8))
						  (let ((g (make-array 4)))
						    (print (read-sequence g in))
						    (print g)))
						"""
					.formatted(file, file, file, file, file))) {
			evaluator.eval(expr);
		}
		assertThat(captured.toString(StandardCharsets.UTF_8).trim()).isEqualTo(
				"(3 4 3 2)\n#f(1.5 -2.25 3.0e10)\n#d((0.5 -0.0) (0.1 42.0))\n#(1 65535 258)\n#(65536 4294967295)\n#(0 0 192 63)\n3\n#f(9.0 1.5 -2.25 9.0 9.0 9.0)\n4\n#(0 0 192 63)");
	}

	@Test
	void readSequenceOverACharacterBufferDecodesABlockAtATime(@TempDir Path tempDir) {
		// The CHARACTER arm of read-sequence moves a block of storage units per call
		// (.kb/character-sequence-io.md) and must answer exactly what the per-character
		// loop answered: one code point per slot whatever its encoded width, a sequence
		// split by the end of a block carried across it, :start/:end honoured, and the
		// stream left exactly where the last character ended. The 8,191 leading
		// characters put the non-BMP one ON the 8,192-unit block boundary, which is the
		// case a per-character read cannot get wrong and a block read can.
		String file = tempDir.resolve("cs.txt").toString().replace("\\", "\\\\");
		java.io.ByteArrayOutputStream captured = new java.io.ByteArrayOutputStream();
		LispEvaluator evaluator = new LispEvaluator(new PrintStream(captured, true, StandardCharsets.UTF_8));
		for (LispVal expr : LispReader.readAllFromString("""
				(with-open-file (out "%s" :direction :output :if-exists :supersede)
				  (write-string (make-string 8191 :initial-element #\\x) out)
				  (write-string (concatenate 'string (string (code-char 128512)) "a"
				                             (string (code-char 12354)) "b")
				                out))
				(with-open-file (in "%s")
				  (let ((buf (make-string 8196 :initial-element #\\.)))
				    (print (read-sequence buf in))
				    (print (list (char-code (char buf 8190)) (char-code (char buf 8191))
				                 (char buf 8192) (char-code (char buf 8193)) (char buf 8194)
				                 (char buf 8195)))))
				(with-open-file (in "%s")
				  (let ((head (make-string 3 :initial-element #\\.))
				        (tail (make-string 5 :initial-element #\\.)))
				    (print (read-sequence head in))
				    (print (read-sequence tail in :start 1 :end 4))
				    (print (list head tail))))
				""".formatted(file, file, file))) {
			evaluator.eval(expr);
		}
		assertThat(captured.toString(StandardCharsets.UTF_8).trim())
			.isEqualTo("8195\n(120 128512 #\\a 12354 #\\b #\\.)\n3\n4\n(\"xxx\" \".xxx.\")");
	}

	@Test
	void evalBinaryStandardStreamsAreByteTransparent() {
		// stdin -> stdout as octets: the bytes below are a NUL, a high byte and a
		// newline plus one UTF-8 lead byte, none of which may be decoded, re-encoded or
		// line-buffered on the way through. The spelling is CL's own -- the standard
		// stream variables hold the t designator, so no handle is involved.
		byte[] octets = { 'h', 'i', 0, (byte) 0xE6, (byte) 0x97, (byte) 0xA5, (byte) 0xFF, '\n', 'z' };
		java.io.ByteArrayOutputStream captured = new java.io.ByteArrayOutputStream();
		PrintStream out = new PrintStream(captured, true, StandardCharsets.UTF_8);
		LispEvaluator evaluator = new LispEvaluator(out, new ByteArrayInputStream(octets));
		for (LispVal expr : LispReader.readAllFromString("""
				(let ((b (read-byte *standard-input* nil nil)))
				  (while b
				    (write-byte b *standard-output*)
				    (setq b (read-byte *standard-input* nil nil))))
				""")) {
			evaluator.eval(expr);
		}
		out.flush();
		assertThat(captured.toByteArray()).isEqualTo(octets);
	}

	@Test
	void evalBinaryStandardStreamDesignators() {
		// nil and t are the same two designators every other stream operation takes, and
		// read-sequence / write-sequence inherit them through their read-byte /
		// write-byte lowering.
		java.io.ByteArrayOutputStream captured = new java.io.ByteArrayOutputStream();
		PrintStream out = new PrintStream(captured, true, StandardCharsets.UTF_8);
		LispEvaluator evaluator = new LispEvaluator(out, new ByteArrayInputStream(new byte[] { 65, 66, 67 }));
		LispVal result = LispNil.INSTANCE;
		for (LispVal expr : LispReader.readAllFromString("""
				(setq buf (make-array 4 :initial-element 0))
				(setq filled (read-sequence buf t))
				(write-byte 62 nil)
				(write-sequence buf t :end filled)
				(write-byte 60 *standard-output*)
				(read-byte *standard-input* nil :eof)
				""")) {
			result = evaluator.eval(expr);
		}
		out.flush();
		assertThat(captured.toString(StandardCharsets.UTF_8)).isEqualTo(">ABC<");
		// The stream is drained, so the eof-value comes back instead of a signal.
		assertThat(result).isEqualTo(new LispSymbol(":EOF"));
	}

