	@Test
	void vectorPushExtendGrowthPolicyIsDoubling() {
		// The ONE growth policy (am.ik.rontolisp.ArrayGrowth), pinned here and in the
		// JVM / WASM twins and the vector-push-extend-growth-cross-backend ci-spec case:
		// a supplied extension verbatim, otherwise doubling off a floor of 1. The
		// numbers are SBCL 2.2.9's (measured 2026-08-31).
		assertThat(evalMulti("""
				(defun growth-run (cap n)
				  (let ((v (make-array cap :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend i v))
				    (array-dimension v 0)))
				(defun growth-run-string (cap n)
				  (let ((s (make-array cap :element-type 'character :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend #\\a s))
				    (array-dimension s 0)))
				(defun growth-run-ext (cap n ext)
				  (let ((v (make-array cap :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend i v ext))
				    (array-dimension v 0)))
				(list (growth-run 2 5) (growth-run-string 2 5) (growth-run 0 1)
				      (growth-run 0 5) (growth-run-ext 2 3 100) (growth-run-ext 2 5 1))
				""").print()).isEqualTo("(8 8 1 8 102 5)");
	}

	@Test
	void aSlotOpenedByGrowthTakesTheElementTypeZero() {
		// A slot the GROWTH opens is below the new DIMENSION but above the fill
		// pointer, so aref may read it, and it answers the array's remembered element
		// type's own zero -- the same fill make-array gives an unsupplied element
		// (am.ik.rontolisp.ArrayElementTypes). #\Space is this project's ONE character
		// fill; the general vector keeps NIL. adjust-array opens the same kind of slot
		// and takes the same fill. Pinned here, in the other three backends' twins and
		// in the opened-slot-fill-cross-backend ci-spec case.
		assertThat(evalMulti("""
				(defun opened-push (cap n)
				  (let ((v (make-array cap :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend i v))
				    (aref v (1- (array-dimension v 0)))))
				(defun opened-push-string (cap n)
				  (let ((s (make-array cap :element-type 'character :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend #\\a s))
				    (char-code (aref s (1- (array-dimension s 0))))))
				(defun opened-push-typed (cap n)
				  (let ((f (make-array cap :element-type 'double-float :fill-pointer 0 :adjustable t))
				        (b (make-array cap :element-type '(unsigned-byte 8) :fill-pointer 0 :adjustable t)))
				    (dotimes (i n) (vector-push-extend 1.5d0 f))
				    (dotimes (i n) (vector-push-extend 7 b))
				    (list (aref f (1- (array-dimension f 0))) (aref b (1- (array-dimension b 0))))))
				(defun opened-adjust ()
				  (let ((s (make-array 2 :element-type 'character :fill-pointer 1 :adjustable t))
				        (f (make-array 2 :element-type 'double-float :fill-pointer 1 :adjustable t))
				        (v (make-array 2 :fill-pointer 1 :adjustable t)))
				    (adjust-array s 5)
				    (adjust-array f 5)
				    (adjust-array v 5)
				    (list (char-code (aref s 4)) (aref f 4) (aref v 4))))
				(list (opened-push 2 3) (opened-push-string 2 3) (opened-push-typed 2 3)
				      (opened-adjust))
				""").print()).isEqualTo("(NIL 32 (0.0 0) (32 0.0 NIL))");
	}

	@Test
	void anAdjustedCopyKeepsTheElementType() {
		// adjust-array does not change an array's element type (CLHS), and a
		// NON-adjustable adjustment answers a FRESH array, so the copy has to remember
		// what the original did -- otherwise an adjusted character vector stops
		// answering stringp. A literal (immutable) string is the same question over the
		// one array shape that carries no header at all, and the string shape readers
		// below are what its adjustment goes through. Pinned here, in the other three
		// backends' twins and in the adjusted-copy-element-type-cross-backend ci-spec
		// case.
		assertThat(evalMulti("""
				(defun adjusted-copy-keeps-type ()
				  (let* ((s (make-array 3 :element-type 'character :initial-element #\\x))
				         (r (adjust-array s 5)))
				    (list (stringp r) (array-element-type r) (char-code (aref r 4)))))
				(defun adjusted-literal-string ()
				  (let ((r (adjust-array "abc" 5)))
				    (list (stringp r) (array-element-type r) (length r))))
				(defun adjusted-rank-2-keeps-type ()
				  (let* ((a (make-array '(2 2) :element-type 'character :initial-element #\\y))
				         (r (adjust-array a '(3 3))))
				    (list (array-element-type r) (stringp r) (aref r 2 2))))
				(defun adjusted-typed-keeps-type ()
				  (let* ((f (make-array 3 :element-type 'double-float :fill-pointer 0))
				         (b (make-array '(2 2) :element-type '(unsigned-byte 8)))
				         (rf (adjust-array f 5))
				         (rb (adjust-array b '(3 3))))
				    (list (array-element-type rf) (aref rf 4) (array-element-type rb) (aref rb 2 2))))
				(defun string-is-a-rank-1-array ()
				  (list (array-rank "abc") (array-dimensions "abc") (array-total-size "abc")
				        (array-displacement "abc")))
				(list (adjusted-copy-keeps-type) (adjusted-literal-string) (adjusted-rank-2-keeps-type)
				      (adjusted-typed-keeps-type) (string-is-a-rank-1-array))
				""").print()).isEqualTo("((T CHARACTER 32) (T CHARACTER 5) (CHARACTER NIL #\\Space)"
				+ " (DOUBLE-FLOAT 0.0 (UNSIGNED-BYTE 8) 0) (1 (3) 3 NIL))");
	}

	@Test
	void theArrayShapeReadersAcceptEveryStringRepresentation() {
		// A string IS a rank-1 character array, so every array-info reader answers for
		// one: array-dimensions and the three that lower through it (array-rank /
		// array-total-size / array-dimension, and array-row-major-index with them),
		// plus array-has-fill-pointer-p and adjustable-array-p. All three string
		// representations are asked -- the immutable literal that carries no header,
		// the mutable character vector, and the displaced string view -- because they
		// are distinct shapes on the compile backends. The DIMENSION is the CAPACITY,
		// so it stays 5 for a fill-pointered character vector whose length is 2. Every
		// answer is SBCL 2.2.9's on this very program except the displaced view's
		// adjustable-array-p: SBCL answers T for any non-simple array, while rontolisp
		// reports the :adjustable argument verbatim (.kb/adjustable-arrays.md). Pinned
		// here, in the other three backends' twins and in the
		// string-array-shape-readers-cross-backend ci-spec case.
		assertThat(evalMulti("""
				(defun string-shape (x)
				  (list (array-dimensions x) (array-rank x) (array-total-size x)
				        (array-dimension x 0) (array-row-major-index x 1) (length x)
				        (array-has-fill-pointer-p x) (adjustable-array-p x)))
				(defun string-shapes ()
				  (let ((cv (make-array 5 :element-type 'character :fill-pointer 2 :adjustable t
				                          :initial-element #\\a))
				        (adj (make-array 3 :element-type 'character :adjustable t :initial-element #\\b))
				        (view (make-array 3 :element-type 'character :displaced-to "hello"
				                            :displaced-index-offset 1)))
				    (list (string-shape "abc")
				          (string-shape (make-string 4 :initial-element #\\c))
				          (string-shape cv)
				          (string-shape adj)
				          (string-shape view))))
				(string-shapes)
				""").print()).isEqualTo("(((3) 1 3 3 1 3 NIL NIL) ((4) 1 4 4 1 4 NIL NIL)"
				+ " ((5) 1 5 5 1 2 T T) ((3) 1 3 3 1 3 NIL T) ((3) 1 3 3 1 3 NIL NIL))");
	}

