	@Test
	void withSlotsStillSignalsWhenTheBodyReadsAnUnboundSlot() {
		// The entry-time fallback is boundness-guarded; the body's own reads are not --
		// they are the slot itself, and an unbound one signals like any slot-value.
		assertThat(evalMulti("""
				(defclass wsr-box () ((buffer)))
				(handler-case (with-slots (buffer) (make-instance 'wsr-box) buffer)
				  (unbound-slot (e) (cell-error-name e)))
				""").print()).isEqualTo("BUFFER");
	}

	@Test
	void makeArrayCharacterWithFillPointerBuildsAGrowableString() {
		assertThat(evalMulti("""
				(let ((s (make-array 2 :element-type 'character :adjustable t :fill-pointer 0)))
				  (vector-push-extend #\\a s)
				  (vector-push-extend #\\b s)
				  (vector-push-extend #\\c s)
				  (list s (length s) (array-dimension s 0) (adjustable-array-p s) (array-has-fill-pointer-p s)))
				""").print()).isEqualTo("(\"abc\" 3 4 T T)");
	}

	@Test
	void setfOfATheWrappedPlaceIgnoresTheDeclaration() {
		assertThat(evalMulti("""
				(let ((cell (list 1 2)))
				  (incf (the integer (car cell)))
				  cell)
				""").print()).isEqualTo("(2 2)");
	}

	@Test
	void loadTimeValueEvaluatesItsForm() {
		assertThat(eval("(load-time-value (+ 1 2))").print()).isEqualTo("3");
	}

	@Test
	void loadTimeValueEvaluatesOncePerOccurrence() {
		// One occurrence, three calls: the value form runs once (the memo is keyed on
		// the occurrence, so a second occurrence of the same text still runs).
		assertThat(evalMulti("(defvar ltv-n 0)" + " (defun ltv-bump () (setq ltv-n (+ ltv-n 1)) ltv-n)"
				+ " (defun ltv-probe () (load-time-value (ltv-bump)))"
				+ " (defun ltv-other () (load-time-value (ltv-bump)))"
				+ " (list (ltv-probe) (ltv-probe) (ltv-probe) (ltv-other) ltv-n)")
			.print()).isEqualTo("(1 1 1 2 2)");
		// A nil result still counts as computed.
		assertThat(evalMulti(
				"(defvar ltv-m 0)" + " (defun ltv-nil () (load-time-value (progn (setq ltv-m (+ ltv-m 1)) nil)))"
						+ " (list (ltv-nil) (ltv-nil) ltv-m)")
			.print()).isEqualTo("(NIL NIL 1)");
	}

	@Test
	void userMacroExpandsOncePerCallSite() {
		// CL expands a macro call when the code containing it is processed, not on every
		// evaluation: three calls through one call site expand the body once, and a
		// SECOND call site of the same macro expands again (the memo is keyed on the
		// occurrence, like load-time-value above).
		assertThat(
				evalMulti("(defvar ume-n 0)" + " (defmacro ume-probe () (setq ume-n (+ ume-n 1)) (list 'quote ume-n))"
						+ " (defun ume-here () (ume-probe))" + " (defun ume-there () (ume-probe))"
						+ " (list (ume-here) (ume-here) (ume-here) (ume-there) ume-n)")
					.print())
			.isEqualTo("(1 1 1 2 2)");
	}

	@Test
	void redefiningAMacroReexpandsItsCallSites() {
		// The memoized expansion is only valid for the definitions that produced it.
		assertThat(evalMulti("(defmacro ume-v () 1)" + " (defun ume-read () (ume-v))" + " (defvar ume-first (ume-read))"
				+ " (defmacro ume-v () 2)" + " (list ume-first (ume-read))")
			.print()).isEqualTo("(1 2)");
	}

	@Test
	void aRewrittenBuiltinMacroFormKeepsItsFirstExpansion() {
		// The stated semantic change of the built-in expansion memo
		// (.kb/interpreter-expansion-memo.md): a built-in macro FORM rewritten between
		// two evaluations keeps its FIRST expansion, deliberately -- the compile
		// backends expand once at compile time and can never see such a rewrite, and
		// defmacro call sites were already memoized above. Only the form's own shape
		// is frozen; mutating data the form's subforms evaluate to is unaffected.
		assertThat(evalMulti("(defvar bmm-form (list 'when t 5))" + " (defvar bmm-first (eval bmm-form))"
				+ " (rplaca (cdr bmm-form) nil)" + " (list bmm-first (eval bmm-form))")
			.print()).isEqualTo("(5 5)");
	}

	@Test
	void aMemoizedBuiltinMacroDoesNotHoldTheMemoWhileItsExpansionRuns() throws Exception {
		// The expansion memo is a CACHE, not a lock over evaluation. Evaluating a
		// memoized form under the memo's monitor puts a whole program inside it -- and a
		// program can hand over to another thread (the macOS main thread, a socket
		// read), which then cannot take the monitor to evaluate a memoized form of its
		// own. Both halves park. The memo must be read under the monitor and the
		// expansion evaluated outside it.
		LispEvaluator evaluator = new LispEvaluator(new PrintStream(new ByteArrayOutputStream()));
		for (LispVal form : LispReader.readAllFromString("(when t 1)")) {
			evaluator.eval(form); // memoize the call site
		}
		LispVal slow = LispReader.readFromString("(when t (%sleep-ms 3000))");
		evaluator.eval(slow); // memoize the slow call site too, so the next run hits
		CountDownLatch running = new CountDownLatch(1);
		Thread holder = new Thread(() -> {
			running.countDown();
			evaluator.eval(slow);
		});
		holder.setDaemon(true);
		holder.start();
		running.await();
		Thread.sleep(300); // let the holder get inside the memoized evaluation
		LispVal quick = LispReader.readFromString("(when t 1)");
		long start = System.nanoTime();
		evaluator.eval(quick);
		long elapsedMs = (System.nanoTime() - start) / 1_000_000;
		holder.interrupt();
		assertThat(elapsedMs).as("a memo hit on another thread must not block this evaluation").isLessThan(1000);
	}

	@Test
	void macroletEnteringAndLeavingScopeInvalidatesTheExpansionMemo() {
		// A macrolet replaces the macro table for its dynamic extent, so the same call
		// site means something different inside it -- and the global meaning again after.
		assertThat(evalMulti("(defmacro ume-ml () :global)" + " (defun ume-ml-call () (ume-ml))"
				+ " (list (ume-ml-call) (macrolet ((ume-ml () :local)) (ume-ml-call)) (ume-ml-call))")
			.print()).isEqualTo("(:GLOBAL :LOCAL :GLOBAL)");
	}

	@Test
	void ieee754BitsRoundTripDoublesAsUnsignedIntegers() {
		assertThat(eval("(list (%ieee754-double-bits 1.0d0) (%ieee754-double-from-bits 4607182418800017408))").print())
			.isEqualTo("(4607182418800017408 1.0)");
		// The sign bit makes the unsigned bits a bignum beyond Long.MAX_VALUE.
		assertThat(eval("(%ieee754-double-bits -2.0d0)").print()).isEqualTo("13835058055282163712");
	}

	@Test
	void bfloat16BitsAndBackRoundTripEveryPattern() {
		assertThat(eval("(list (rontolisp:bfloat16-bits 1.0) (rontolisp:bfloat16-bits -2.5)"
				+ " (rontolisp:bits-bfloat16 16256) (rontolisp:bits-bfloat16 (rontolisp:bfloat16-bits 0.1)))")
			.print()).isEqualTo("(16256 49184 1.0 0.10009765625)");
		// Round to nearest EVEN, both directions: 1.00390625 and 1.01171875 are the two
		// exact midpoints either side of 1.005859375, and a truncating narrowing would
		// answer 16256 and 16257 instead.
		assertThat(eval("(list (rontolisp:bfloat16-bits 1.00390625) (rontolisp:bfloat16-bits 1.01171875))").print())
			.isEqualTo("(16256 16258)");
		// Widening is exact and total, so the pair is an involution on every pattern.
		assertThat(eval("(let ((bad 0)) (dotimes (i 65536 bad)"
				+ " (unless (= i (rontolisp:bfloat16-bits (rontolisp:bits-bfloat16 i))) (incf bad))))")
			.print()).isEqualTo("0");
		// An integer argument coerces like any other real, and a first-class reference
		// reaches the same answer through the wrapper.
		assertThat(eval("(list (rontolisp:bfloat16-bits 2) (mapcar #'rontolisp:bfloat16-bits (list 1.0 2.0)))").print())
			.isEqualTo("(16384 (16256 16384))");
	}

	@Test
	void bfloat16BulkNarrowingIsTheSameRoundingAsTheScalarPair() {
		// .todo/671's bulk pair and .todo/487's scalar pair are ONE rounding
		// (am.ik.rontolisp.BFloat16), not two copies of it: a checkpoint's bulk load
		// must not sit a bit away from what the program computes element by element.
		// Widening every pattern into an f32 array and narrowing it straight back is
		// what says so -- the plain identity over all 65536 patterns, NaN payloads
		// included: widen-float-bits stores the bit pattern verbatim (a bfloat16
		// pattern IS an f32's top half already, so widening is one shift, never a
		// double), and narrow-float-bits' float-source arm rounds on the float's raw
		// bits directly rather than through BFloat16.bits(double) (whose parameter
		// would auto-widen a float argument first) -- so nothing here ever touches a
		// double, and nothing quiets a signalling NaN.
		assertThat(eval("""
				(let* ((n 65536)
				       (patterns (make-array n :element-type '(unsigned-byte 16)))
				       (values (make-array n :element-type 'single-float))
				       (back (make-array n :element-type '(unsigned-byte 16)))
				       (bad 0))
				  (dotimes (i n) (setf (aref patterns i) i))
				  (rontolisp:widen-float-bits patterns :bfloat16 values)
				  (rontolisp:narrow-float-bits values :bfloat16 back)
				  (dotimes (i n bad)
				    (unless (= i (aref back i)) (incf bad))))
				""").print()).isEqualTo("0");
		// And element for element against the scalar, over the values an f32 array can
		// actually hold (every pattern -- storing one is exact, per the section above).
		assertThat(eval("""
				(let* ((n 65536)
				       (values (make-array n :element-type 'single-float))
				       (back (make-array n :element-type '(unsigned-byte 16)))
				       (bad 0))
				  (dotimes (i n) (setf (aref values i) (rontolisp:bits-bfloat16 i)))
				  (rontolisp:narrow-float-bits values :bfloat16 back)
				  (dotimes (i n bad)
				    (unless (= (aref back i) (rontolisp:bfloat16-bits (aref values i))) (incf bad))))
				""").print()).isEqualTo("0");
	}

	@Test
	void float16BitsAndBackRoundTripEveryFinitePattern() {
		assertThat(eval("(list (rontolisp:float16-bits 1.0) (rontolisp:float16-bits -2.5)"
				+ " (rontolisp:bits-float16 15360) (rontolisp:bits-float16 (rontolisp:float16-bits 1.5)))")
			.print()).isEqualTo("(15360 49408 1.0 1.5)");
		// Widening then narrowing is the identity for every pattern EXCEPT the JDK's own
		// float16ToFloat/floatToFloat16 pair does not itself round-trip a signalling NaN
		// to the same pattern (it quiets on the way to float) -- so the check below
		// skips NaN, matching .todo/671's ci-spec.yaml case and its "NaN payload aside"
		// convention for this pair specifically (unlike bfloat16-bits above, which IS
		// exact and total, including NaN, per BFloat16's own contract).
		assertThat(eval("""
				(let ((bad 0))
				  (dotimes (i 65536 bad)
				    (let ((v (rontolisp:bits-float16 i)))
				      (when (= v v)
				        (unless (= i (rontolisp:float16-bits v)) (incf bad))))))
				""").print()).isEqualTo("0");
		// An integer argument coerces like any other real, and a first-class reference
		// reaches the same answer through the wrapper.
		assertThat(eval("(list (rontolisp:float16-bits 2) (mapcar #'rontolisp:float16-bits (list 1.0 2.0)))").print())
			.isEqualTo("(16384 (15360 16384))");
	}

	@Test
	void widenAndNarrowFloatBitsShareTheScalarPairsRounding() {
		// float16, into and out of a single-float array, with a nonzero :start (the
		// packed array's header-offset arithmetic on the compiled backends).
		assertThat(eval("""
				(let* ((bits (make-array 3 :element-type '(unsigned-byte 16)
				                         :initial-contents (list (rontolisp:float16-bits 1.0)
				                                                  (rontolisp:float16-bits -2.5)
				                                                  (rontolisp:float16-bits 100.0))))
				       (dst (make-array 5 :element-type 'single-float :initial-element 0.0))
				       (back (make-array 5 :element-type '(unsigned-byte 16))))
				  (rontolisp:widen-float-bits bits :float16 dst :start 2)
				  (rontolisp:narrow-float-bits dst :float16 back)
				  (list (aref dst 0) (aref dst 1) (aref dst 2) (aref dst 3) (aref dst 4)
				        (aref back 0) (aref back 1) (aref back 2) (aref back 3) (aref back 4)))
				""").print()).isEqualTo("(0.0 0.0 1.0 -2.5 100.0 0 0 15360 49408 22080)");
		// A length-1 tensor: the shape that caught the JVM arm's one real bug (the
		// packed-float header offset), so it stays pinned on its own.
		assertThat(eval("""
				(let* ((bits (make-array 1 :element-type '(unsigned-byte 16)
				                         :initial-contents (list (rontolisp:float16-bits -2.5))))
				       (dst (make-array 1 :element-type 'single-float)))
				  (rontolisp:widen-float-bits bits :float16 dst)
				  (aref dst 0))
				""").print()).isEqualTo("-2.5");
		// A double-float destination/source works the same way.
		assertThat(eval("""
				(let* ((bits (make-array 2 :element-type '(unsigned-byte 16)
				                         :initial-contents (list (rontolisp:float16-bits 3.5)
				                                                  (rontolisp:float16-bits -7.25))))
				       (dst (make-array 2 :element-type 'double-float))
				       (back (make-array 2 :element-type '(unsigned-byte 16))))
				  (rontolisp:widen-float-bits bits :float16 dst)
				  (rontolisp:narrow-float-bits dst :float16 back)
				  (list (aref dst 0) (aref dst 1) (aref back 0) (aref back 1)))
				""").print()).isEqualTo("(3.5 -7.25 17152 51008)");
		// First-class references reach the same primitive the special form does.
		assertThat(eval("""
				(let ((bits (make-array 1 :element-type '(unsigned-byte 16) :initial-element 15360))
				      (dst (make-array 1 :element-type 'single-float)))
				  (funcall #'rontolisp:widen-float-bits bits :float16 dst)
				  (aref dst 0))
				""").print()).isEqualTo("1.0");
	}

